from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
l=Lesson('Difficulté à avaler, étouffement')
l.add('Une difficulté à avaler peut concerner la déglutition ou la progression dans l’œsophage. Les {distinctions initiales} séparent dysphagie, douleur et obstruction respiratoire. Une personne qui ne peut plus parler ou tousser nécessite une action immédiate.',paras('La dysphagie est une difficulté à transporter efficacement et sûrement aliments ou liquides de la bouche vers l’estomac. L’odynophagie désigne une douleur à la déglutition ; les deux symptômes peuvent coexister.', 'Une sensation de boule dans la gorge, ou globus, n’est pas automatiquement une dysphagie. Il faut préciser le lien avec les repas et rechercher de vrais signes d’obstacle ou de mauvaise protection respiratoire.', 'L’étouffement aigu par corps étranger concerne les voies aériennes. Une impaction œsophagienne peut laisser la personne respirer tout en l’empêchant d’avaler sa salive ; elle reste une urgence distincte.'),(1,2,5,6,7))
l.add('La dysphagie survient dans des contextes variés, notamment neurologiques, structuraux et inflammatoires. Les {limites épidémiologiques} empêchent d’appliquer un classement suisse unique. Le terrain et la gravité déterminent les priorités.',paras('Les troubles sont particulièrement importants après AVC, dans les maladies neurodégénératives, chez les personnes fragiles et après certains traitements oncologiques. Ils exposent à dénutrition, déshydratation et complications respiratoires.', 'Les fréquences publiées dépendent des populations, définitions et méthodes de dépistage. Une proportion mesurée en institution ou après AVC ne représente pas tous les patients consultant en Suisse.', 'Les dix diagnostics sont un choix pédagogique couvrant mécanismes fréquents ou importants et urgences. Leur ordre ne prétend pas reproduire des prévalences suisses comparables non disponibles.'),(1,3,5,9))
anatomie=l.subwindow('anatomie','Phases et protection des voies aériennes',paras('Phase orale : préparer le bol par mastication, le contenir puis le propulser avec la langue. Phase pharyngée : transférer le bol en coordonnant la protection laryngée et l’ouverture du sphincter supérieur de l’œsophage. Phase œsophagienne : le transport péristaltique et l’ouverture de la jonction avec l’estomac permettent la progression.', 'Le pharynx participe au passage des aliments ; une fausse route correspond à leur entrée dans les voies respiratoires, pas au simple passage dans le pharynx. La protection respiratoire repose sur plusieurs mécanismes coordonnés et ne se réduit pas à l’épiglotte.', 'Une fermeture laryngée inadéquate, une réponse retardée, des résidus ou une ouverture sphinctérienne insuffisante peuvent compromettre sécurité ou efficacité. Une toux absente n’exclut pas une aspiration : la sensibilité ou la réponse motrice peuvent être diminuées.'),(1,2,5))
l.add('Avaler exige une coordination de la bouche, du pharynx, du larynx et de l’œsophage. Les {bases anatomiques et physiologiques} expliquent les différents symptômes. Un trouble peut compromettre le transport, la protection respiratoire ou les deux.',paras(anatomie)+paras('Un rétrécissement mécanique gêne le passage, souvent d’abord des solides. Un trouble moteur peut perturber solides et liquides ; ces profils orientent mais ne posent pas seuls le diagnostic.', 'Une maladie neurologique ou neuromusculaire peut altérer force, coordination et sensibilité. La localisation ressentie dans le cou ne prouve pas que la lésion y siège.', 'Inflammation, fibrose et trouble de relaxation peuvent se combiner. L’achalasie associe une mauvaise relaxation de la jonction œsogastrique et une anomalie majeure du péristaltisme ; l’œsophagite à éosinophiles peut évoluer vers un remodelage sténosant.'),(1,2,5))
l.add('Les {urgences à exclure} concernent d’abord respiration, obstruction complète et signes neurologiques récents. L’impossibilité d’avaler la salive est un signal majeur. Amaigrissement et progression demandent aussi un bilan rapide.',table(['Priorité','🚩 Constat','Conduite'],[['E1 — Voies aériennes.','Toux inefficace, impossibilité de parler, cyanose ou perte de connaissance.','Appel 144 et désobstruction/réanimation selon état et âge.'],['E2 — Obstruction œsophagienne complète.','Blocage brutal et salive impossible à avaler.','Rien par bouche ; prise en charge endoscopique en urgence.'],['E3 — Neurologique.','Dysphagie avec déficit brutal, trouble de parole ou faiblesse respiratoire.','Filière urgente ; éviter les prises orales non évaluées.'],['E4 — Complication ou autre atteinte cervicale.','Douleur thoracique ou cervicale sévère, fièvre, tuméfaction, stridor ou suspicion de perforation.','Évaluation urgente et protection des voies aériennes selon besoin.'],['E5 — Cause tumorale ou retentissement.','Progression, perte pondérale, saignement, déshydratation ou pneumonies répétées.','Bilan rapide et soutien nutritionnel/respiratoire.']]),(1,5,6,7,8,9))
l.add('L’entretien précise le moment de la gêne et son évolution. Les {questions ciblées} recherchent fausses routes, obstacle et facteurs associés. L’absence de toux ne suffit pas à rassurer.',table(['Question','Utilité'],[['Difficulté à initier ou sensation de blocage après avoir avalé ?','Oriente le mécanisme, sans localisation certaine.'],['Solides, liquides ou les deux, dès le début ou progressivement ?','Oriente obstacle ou dysmotilité sans remplacer les examens.'],['Début brutal pendant un repas, salive avalable ?','Recherche une impaction et son degré.'],['Toux, voix mouillée, régurgitation nasale, repas prolongés ?','Recherche une dysphagie oropharyngée.'],['Régurgitations, reflux, impactions antérieures, atopie ?','Recherche causes œsophagiennes et inflammatoires.'],['Poids, apports, fièvre, pneumonies ou déshydratation ?','Mesure les conséquences et la gravité.'],['AVC, Parkinson, fatigabilité, chirurgie/radiothérapie, médicaments ?','Identifie terrain neurologique, iatrogène ou structurel.'],['Évitements alimentaires et adaptations spontanées ?','Peuvent masquer la sévérité et un retard diagnostique.']]),(1,2,3,5,6,9))
l.add('L’examen commence par respiration, conscience et gestion des sécrétions. Les {éléments cliniques} orientent le bilan et la sécurité de l’alimentation. Un essai de boisson n’est pas un geste automatique.',paras('Observer voix, toux, posture, état buccodentaire et mobilité de langue, lèvres, mâchoire et palais. Examiner le cou et rechercher signes neurologiques, déficit focal ou fatigabilité selon le tableau.', 'Évaluer poids, hydratation, apports et signes respiratoires. Le dépistage clinique de déglutition suit un protocole adapté, réalisé par un professionnel formé chez un patient dont l’état le permet.', 'Après AVC aigu, ne pas donner aliment, boisson ou médicament oral avant dépistage et jugement de sécurité. Si obstruction complète, altération de conscience ou détresse respiratoire, la prise en charge urgente précède tout essai alimentaire.', 'Une évaluation clinique seule peut manquer une aspiration silencieuse et ne suffit pas à caractériser définitivement toute dysphagie oropharyngée.'),(2,3,5,9))
l.add('L’{approche syndromique} distingue transport oropharyngé, passage œsophagien et obstruction respiratoire. Plusieurs mécanismes peuvent coexister. Les conséquences nutritionnelles et respiratoires doivent être évaluées séparément.',table(['Syndrome','Indices','Exploration'],[['7.1 — Oropharyngé.','Difficulté d’initiation, résidus, voix mouillée, toux ou fausse route silencieuse.','Bilan de déglutition puis FEES/VFSS selon indication.'],['7.2 — Œsophagien mécanique.','Blocage surtout aux solides, progressif ou intermittent.','Endoscopie avec prélèvements adaptés.'],['7.3 — Œsophagien moteur.','Solides et liquides, régurgitations, bilan structural non explicatif.','Manométrie après bilan endoscopique.'],['7.4 — Impaction aiguë.','Aliment bloqué brutalement, parfois salive impossible.','Endoscopie urgente selon obstruction et risque.'],['7.5 — Respiratoire obstructif.','Toux inefficace, silence ou impossibilité de parler.','Gestes immédiats, sans attendre une exploration digestive.'],['7.6 — Douloureux ou cervical.','Odynophagie, masse, fièvre ou lésion buccale.','Bilan ORL, infectieux ou œsophagien adapté.']]),(1,2,5,6,7,9))
l.add('Le symptôme ne constitue pas à lui seul un diagnostic causal. Les {dix diagnostics retenus} couvrent plusieurs mécanismes et niveaux d’urgence. Les autres causes menaçantes restent à rechercher selon le tableau.',paras('Un reflux connu ne permet pas de qualifier une dysphagie de bénigne sans bilan. Une endoscopie d’aspect normal n’exclut pas une œsophagite à éosinophiles et un bilan organique négatif doit précéder un diagnostic fonctionnel.', 'Angioœdème, épiglottite ou infection cervicale profonde, lésion ORL tumorale, œsophagite infectieuse ou médicamenteuse et compression extrinsèque peuvent aussi expliquer une gêne. Ils ne sont pas exclus par leur absence des dix monographies.', 'Le bilan doit distinguer l’épisode, par exemple l’impaction, de sa cause sous-jacente, par exemple sténose ou inflammation éosinophilique.')+comparison(),(1,5,6))
l.add('Les examens se choisissent selon le mécanisme suspecté et l’urgence. Les {quatre niveaux du bilan} précisent le rôle de chaque technique. Une exploration normale ne met pas fin au raisonnement si les symptômes persistent.',paras('9.a — Référence : évaluation clinique ciblée puis examen adapté au mécanisme ; aucun test unique ne couvre toutes les dysphagies.', '9.b — Dysphagie oropharyngée : FEES ou VFSS pour observer protection respiratoire, résidus et efficacité, y compris aspiration silencieuse. Leur choix dépend de la question, du patient et des ressources ; les essais de textures peuvent guider un plan individuel.', '9.c — Dysphagie œsophagienne adulte : endoscopie haute, avec biopsies selon les recommandations et particulièrement si une œsophagite à éosinophiles est possible même sans anomalie visible. Les recommandations européennes citent au moins six biopsies à au moins deux niveaux œsophagiens pour cette recherche.', '9.d — Si le bilan endoscopique n’explique pas les symptômes, manométrie haute résolution pour la motricité. Transit œsophagien et autres techniques sont des compléments ciblés, notamment pour anatomie ou vidange ; une suspicion de perforation ou d’obstruction aiguë modifie le parcours et ne doit pas être retardée par un examen de routine.'),(2,5,6))
l.add('L’{arbre décisionnel} sépare urgence vitale, obstruction digestive et dysphagie stable. Le soutien des apports se prépare en parallèle du bilan causal. Le suivi vérifie que l’alimentation reste sûre et suffisante.',steps('Toux inefficace ou impossibilité de parler → 144 et gestes adaptés à l’état et à l’âge.', 'Si respiration préservée mais salive impossible à avaler après blocage → rien par bouche et endoscopie en urgence.', 'Déficit neurologique récent, détresse ou complication → filière urgente adaptée.', 'Sans urgence immédiate → rechercher syndrome oropharyngé ou œsophagien et planifier les examens appropriés.', 'Évaluer sécurité, hydratation, nutrition et voie des médicaments ; adapter provisoirement avec l’équipe.', 'Traiter la cause identifiée puis contrôler symptômes, apports, poids et complications.'),(1,2,5,6,7,8,9))
adulte=l.subwindow('urgence-adulte','Étouffement : adulte conscient puis inconscient',paras('Si la personne tousse efficacement et peut parler, encourager la toux et surveiller sans manœuvres inutiles. Faire appeler le 144 précocement si l’obstruction devient sévère, idéalement par une autre personne pendant l’aide.', 'Si la toux devient inefficace, pencher la personne en avant et donner jusqu’à cinq claques entre les omoplates. En cas d’échec, effectuer jusqu’à cinq compressions abdominales, puis alterner les deux séries tant que la personne reste consciente et obstruée. Arrêter dès la levée de l’obstruction.', 'Pour les compressions abdominales, se placer derrière, entourer l’abdomen et placer le poing entre nombril et extrémité inférieure du sternum ; saisir le poing et exercer un mouvement brusque vers l’intérieur et le haut. Les situations particulières demandent une adaptation par un sauveteur formé et les instructions du 144.', 'Si la personne devient inconsciente, l’accompagner au sol, faire appeler les secours et commencer la RCP. L’algorithme SRC adulte utilise trente compressions thoraciques suivies de deux insufflations ; faire apporter et utiliser un DAE selon ses instructions. Suivre le guidage du 144 si la technique n’est pas maîtrisée.', 'Ne pas faire de balayage digital à l’aveugle. Retirer seulement un objet clairement visible et accessible. Après des compressions abdominales ou thoraciques ayant levé l’obstruction, une évaluation médicale recherche une lésion ou un corps étranger résiduel.'),(4,7))
enfant=l.subwindow('urgence-enfant','Étouffement : nourrisson et enfant',paras('Faire appeler les secours rapidement. Si la toux est efficace, encourager l’enfant et surveiller. Si elle est inefficace, donner jusqu’à cinq claques dorsales, avec position et soutien adaptés à l’âge, puis jusqu’à cinq poussées si nécessaire.', 'Chez le nourrisson, soutenir tête et tronc, tête plus basse que le thorax pour les claques dorsales. Les poussées sont thoraciques, jamais abdominales ; les recommandations pédiatriques 2025 décrivent la technique des deux pouces avec mains entourant le thorax, plus brusque que les compressions ordinaires.', 'Chez l’enfant plus grand, pencher vers l’avant pour les claques et utiliser des compressions abdominales si elles échouent. Alterner les séries seulement tant que l’obstruction sévère persiste et arrêter dès la reprise d’une toux efficace, de cris ou d’une respiration utile.', 'Si l’enfant devient inconscient, commencer la réanimation avec cinq insufflations initiales puis compressions et ventilations. Le rapport est quinze pour deux pour un sauveteur formé en réanimation pédiatrique ; le guidage destiné à un témoin non formé ou formé seulement chez l’adulte utilise trente pour deux après les cinq insufflations. Suivre le 144 sans retarder l’aide.', 'Ne jamais chercher un objet à l’aveugle avec les doigts. Un objet visible et accessible peut être retiré. Ces gestes demandent une formation pratique ; les dispositifs d’aspiration commercialisés ne remplacent pas le parcours standard faute de données suffisantes.'),(4,8))
l.add('La prise en charge protège d’abord respiration et déglutition, puis traite la cause. Les {modalités pratiques} distinguent gestes d’urgence et réadaptation. Il n’existe pas de médicament universel de la dysphagie.',paras('11.A — Préserver les voies aériennes, assurer hydratation et nutrition, identifier la cause et maintenir autant que possible autonomie et plaisir de manger.',adulte,enfant,'11.B — En cas d’impaction œsophagienne complète, l’ESGE recommande une endoscopie de préférence dans les deux heures et au plus tard dans les six heures. Pour une impaction sans obstruction complète, le repère est dans les vingt-quatre heures. Ces délais organisent les soins urgents et ne sont pas une permission d’attendre à domicile.', 'Ne pas tenter de pousser un aliment avec une nouvelle bouchée ou une boisson en présence d’une obstruction. Un traitement médicamenteux ne doit pas retarder l’endoscopie ; rechercher ensuite la maladie sous-jacente, y compris par histologie.', '11.C — Pour une dysphagie oropharyngée, établir un plan individuel avec logopédie, équipe médicale et nutrition. Adapter posture, taille des bouchées, rythme et textures après évaluation ; une tête fléchie ou des liquides épaissis ne sont pas une solution universelle.', 'Surveiller réellement apports hydriques et nutritionnels si les textures sont modifiées. Si la prise orale est insuffisante ou dangereuse, décider d’une autre voie avec l’équipe et le patient, tout en réévaluant son objectif et sa durée.', '11.D — Maintenir l’hygiène buccodentaire et réviser la forme des médicaments avec médecin et pharmacien. Ne pas écraser une forme retard ou gastro-résistante par défaut ; une adaptation doit être vérifiée produit par produit. Suivre poids, hydratation, épisodes respiratoires, observance et qualité de vie.'),(2,3,4,5,6,7,8,9))
l.add('La prévention associe sécurité des repas, repérage précoce et prise en charge des maladies causales. Les {mesures durables} doivent être adaptées aux capacités et aux souhaits du patient. L’âge seul ne justifie pas de banaliser une dysphagie.',paras('Primaire : aliments et objets adaptés à l’âge, supervision appropriée des jeunes enfants, repas calmes et protection buccodentaire. Former l’entourage aux gestes d’urgence lorsque le risque le justifie.', 'Secondaire : dépister après AVC et rechercher une dysphagie devant pneumonies répétées, perte pondérale ou changements alimentaires. Une absence de plainte ou de toux ne suffit pas.', 'Tertiaire : appliquer et réévaluer le plan de textures, posture et réadaptation ; surveiller hydratation et nutrition et traiter la cause. Après impaction, ne pas clore le dossier au seul retrait du bol.'),(2,3,5,6,8,9))
l.add('Étouffement respiratoire et impaction œsophagienne demandent des conduites différentes. Une fausse route peut être silencieuse. Endoscopie, exploration de déglutition et manométrie répondent à des questions distinctes. Textures et médicaments doivent être adaptés individuellement.',refs=(1,2,3,5,6,7,9))
l.quiz([('L’odynophagie désigne-t-elle un obstacle prouvé ?','Non : elle désigne une douleur à la déglutition.'),('Une personne qui respire mais ne peut plus avaler sa salive est-elle forcément rassurante ?','Non : une obstruction œsophagienne complète reste une urgence.'),('L’absence de toux exclut-elle une aspiration ?','Non : une fausse route peut être silencieuse.'),('La localisation ressentie dans le cou identifie-t-elle toujours la lésion ?','Non : l’histoire oriente sans localisation certaine.'),('Un reflux connu permet-il de négliger une dysphagie progressive ?','Non : un obstacle ou une autre cause doit être recherché.'),('Un œsophage d’aspect normal exclut-il l’œsophagite à éosinophiles ?','Non : les biopsies restent importantes.'),('Quel examen explore principalement la motricité œsophagienne ?','La manométrie haute résolution, après bilan adapté dont l’endoscopie.'),('FEES et VFSS peuvent-elles détecter une aspiration silencieuse ?','Oui : elles servent à caractériser la déglutition et à adapter le plan.'),('Après AVC aigu, faut-il donner un médicament oral avant dépistage ?','Non : attendre que la déglutition soit évaluée et jugée sûre.'),('Faut-il faire des compressions abdominales si la toux reste efficace ?','Non : encourager la toux et surveiller.'),('Les poussées de désobstruction sont-elles abdominales chez le nourrisson ?','Non : elles sont thoraciques.'),('Peut-on balayer la bouche à l’aveugle avec un doigt ?','Non : retirer seulement un objet visible et accessible.'),('Les liquides épaissis dispensent-ils de surveiller l’hydratation ?','Non : apports et bilan hydrique doivent être surveillés.'),('Le retrait d’un aliment bloqué termine-t-il tout bilan ?','Non : rechercher une cause sous-jacente, notamment sténose ou œsophagite à éosinophiles.')],(1,2,3,4,5,6,7,8,9))
l.write()
